// HasCustomer applies the HasEdge predicate on the "customer" edge.
func HasCustomer() predicate.CustomerVehicle {
	return predicate.CustomerVehicle(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CustomerTable, CustomerColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCustomerWith applies the HasEdge predicate on the "customer" edge with a given conditions (other predicates).
func HasCustomerWith(preds ...predicate.CustomerProfile) predicate.CustomerVehicle {
	return predicate.CustomerVehicle(func(s *sql.Selector) {
		step := newCustomerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CustomerVehicle) predicate.CustomerVehicle {
	return predicate.CustomerVehicle(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CustomerVehicle) predicate.CustomerVehicle {
	return predicate.CustomerVehicle(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CustomerVehicle) predicate.CustomerVehicle {
	return predicate.CustomerVehicle(sql.NotPredicates(p))
}
